def Icon(vnum):
	name = PORTRAITS.get(vnum)
	if name:
		return ROOT + name + '.tga'
	if vnum in STONES:
		return ROOT + '_metin.tga'
	if vnum in BOSSES:
		return ROOT + '_boss.tga'
	return ROOT + '_monster.tga'
